evenClasses.statement:
def evenClasses (O : CoeffRing ℓ) S ν e := {c ∈ selmerModule (tateTwist ℓ E O e)
  (placesDividing E ℓ ∪ .conjClosure S) ∅ (QuotSpan (ℓ ^ ν : ↑O)) |
  (∀ g, c (conjGal g) = c g) ∧ ∀ g ∈ shaLocalSet ℓ E 1, c g = 0}

