IsRibetElement.statement:
def IsRibetElement [Fintype J] (β : Y → L) {𝓧 : Set Y} (π : 𝓧) c := (.C <| β ·) ∈ S ∧ ∃ f :
    S, f.1 * (.C <| β ·) ∈ 𝒥 ∧ (∀ x : 𝓧, β x = 0 ∧ ∀ d < ∑ j, .single j 1, (f.1 x).coeff d = 0) ∧
    (f.1 π).coeff (∑ j, .single j 1) = c

